package com.ecommerce.controller;
import com.ecommerce.dto.AdminDtos.*; import com.ecommerce.dto.CatalogDtos.*; import com.ecommerce.dto.OrderDtos.*; import com.ecommerce.repository.*; import com.ecommerce.service.*; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/admin") public class AdminController { private final CatalogService catalog; private final InventoryService inventory; private final OrderService orders; private final UserRepository users; private final ProductRepository products; private final OrderRepository orderRepo; private final PaymentRepository payments; public AdminController(CatalogService catalog,InventoryService inventory,OrderService orders,UserRepository users,ProductRepository products,OrderRepository orderRepo,PaymentRepository payments){this.catalog=catalog;this.inventory=inventory;this.orders=orders;this.users=users;this.products=products;this.orderRepo=orderRepo;this.payments=payments;} @GetMapping("/dashboard") public DashboardResponse dashboard(){return new DashboardResponse(users.count(),products.count(),orderRepo.count(),payments.count());} @PostMapping("/categories") public CategoryResponse createCategory(@Valid @RequestBody CategoryRequest r){return catalog.createCategory(r);} @PostMapping("/products") public ProductResponse createProduct(@Valid @RequestBody ProductRequest r){return catalog.createProduct(r);} @PutMapping("/products/{id}") public ProductResponse updateProduct(@PathVariable Long id,@Valid @RequestBody ProductRequest r){return catalog.updateProduct(id,r);} @PatchMapping("/products/{id}/inventory") public ProductResponse adjustInventory(@PathVariable Long id,@Valid @RequestBody InventoryAdjustmentRequest r){return inventory.adjust(id,r);} @GetMapping("/orders") public List<OrderResponse> allOrders(){return orders.allOrders();} @PatchMapping("/orders/{id}/status") public OrderResponse updateStatus(@PathVariable Long id,@Valid @RequestBody OrderStatusRequest r){return orders.updateStatus(id,r.status());} }